class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        bestIdx, bestDur = events[0][0], events[0][1]
        for i in range(1, len(events)):
            dur = events[i][1] - events[i - 1][1]
            if dur > bestDur or (dur == bestDur and events[i][0] < bestIdx):
                bestDur, bestIdx = dur, events[i][0]
        return bestIdx

c.cpp:
class Solution {
public:
    int buttonWithLongestTime(vector<vector<int>>& events) {
        int bestIdx = events[0][0], bestDur = events[0][1];
        for (int i = 1; i < events.size(); i++) {
            int dur = events[i][1] - events[i - 1][1];
            if (dur > bestDur || (dur == bestDur && events[i][0] < bestIdx)) {
                bestDur = dur;
                bestIdx = events[i][0];
            }
        }
        return bestIdx;
    }
};

